const HTML = "<section class=\"review aim-rise\" style=\"--i:6\" id=\"styles\" aria-labelledby=\"styles-h\">\n        <span class=\"review-flag\">For Connor’s review · not learner copy</span>\n        <h2 class=\"sec-h\" id=\"styles-h\">Text styles for long steps</h2>\n        <article class=\"prose\">\n          <p class=\"rt-label\">Reference · How a week runs</p>\n          <h2 class=\"rt-h2\">Every week has the same rhythm</h2>\n          <p class=\"rt-lead\">One skill a week, one live build on Wednesday, and one hire that starts working the next morning.</p>\n          <p>Your <span class=\"rt-term\">operator</span> runs that week’s <span class=\"rt-term\">skill</span> before the live build, <b>by Tuesday night</b>, and the owner reads what it finds. <i>You don’t need to understand every line yet.</i> The goal is that <mark class=\"rt-hl\">both of you show up Wednesday with the findings open</mark>. Week 1’s skill is <code class=\"rt-code\">Map Your Spend</code>, and you can <a href=\"#\" onclick=\"return false\">see what it reads</a> before you run it.</p>\n          <div class=\"cos\">\n            <div class=\"callout tip\"><svg width=\"18\" height=\"18\"><use href=\"#i-info\"/></svg><p><strong>Tip</strong>Block 30 minutes on Tuesday afternoon for the owner’s read. It’s the part that makes Wednesday fast.</p></div>\n            <div class=\"callout heads_up\"><svg width=\"18\" height=\"18\"><use href=\"#i-alert\"/></svg><p><strong>Heads up</strong>Hires read and draft only. Nothing sends, and nothing changes your books or your CRM.</p></div>\n            <div class=\"callout diy\"><svg width=\"18\" height=\"18\"><use href=\"#i-user\"/></svg><p><strong>Doing it yourself?</strong>If the owner is also the operator, do both reads in one sitting.</p></div>\n          </div>\n          <h3 class=\"rt-h3\">The live build, step by step</h3>\n          <ol class=\"rt-steps\">\n            <li><span><b>The question</b>What this week’s hire should take off someone’s desk.</span></li>\n            <li><span><b>Live reads</b>We run the skill together and read what it finds.</span></li>\n            <li><span><b>The hire lab</b>Your operator builds the hire while we watch.</span></li>\n            <li><span><b>The commit</b>The owner signs the seat card.</span></li>\n          </ol>\n          <blockquote class=\"rt-quote\">“A hire is a skill that runs on a schedule and leaves a draft on one person’s desk.”<cite>The definition we use all course</cite></blockquote>\n          <div class=\"rt-two\">\n            <div class=\"do\"><h4><svg width=\"16\" height=\"16\"><use href=\"#i-check\"/></svg>Do</h4><ul><li>Run the skill before Wednesday</li><li>Bring the findings to the build</li><li>Sign the seat card the same day</li></ul></div>\n            <div class=\"dont\"><h4><svg width=\"16\" height=\"16\"><use href=\"#i-x\"/></svg>Don’t</h4><ul><li>Give a hire send or edit access</li><li>Skip the owner’s read</li><li>Change the seat card after it’s signed</li></ul></div>\n          </div>\n          <div class=\"rt-banner\">The checkpoint closes the week: <span>signed seat card, first-run screenshot, minutes taken over.</span></div>\n          <div class=\"copyblock\"><header><span>Prompt · paste into your AI</span><button class=\"btn btn-secondary btn-sm\" type=\"button\" data-copy><svg width=\"14\" height=\"14\"><use href=\"#i-copy\"/></svg><span class=\"aim-roll\"><span>Copy</span><span aria-hidden=\"true\">Copy</span></span></button></header>\n<pre>Run the Map Your Spend skill on last month’s numbers.\nRead only. Draft the summary for the owner, and don’t send it.</pre></div>\n          <div class=\"stylekey\" aria-label=\"Style names\">\n            <div><b>Lead</b>20 px intro line</div><div><b>Heading · Subheading</b>31 / 25 px</div><div><b>Label</b>Geist Mono caps, forest</div>\n            <div><b>Bold · Italic</b>600 · italic</div><div><b>Highlight</b>energy-bright wash</div><div><b>Key term</b>forest, 600</div>\n            <div><b>Code</b>Geist Mono on bone</div><div><b>Link</b>forest, underlined</div><div><b>Callouts</b>Tip · Heads up · Doing it yourself</div>\n            <div><b>Quote</b>20 px forest, energy rule</div><div><b>Do · Don’t</b>two columns</div><div><b>Banner</b>forest fill, one per step</div>\n          </div>\n        </article>\n\n        <h3 class=\"sec-h\" style=\"margin-top:var(--sp-s5);font-size:20px\">What admins see in the Week Builder</h3>\n        <div class=\"builder\">\n          <div class=\"bfield\">\n            <div class=\"btool\" role=\"toolbar\" aria-label=\"Text styles\">\n              <select aria-label=\"Block style\"><option>Paragraph</option><option>Lead</option><option>Heading</option><option>Subheading</option><option>Label</option><option>Quote</option><option>Banner</option></select>\n              <button class=\"tb\" type=\"button\" aria-label=\"Bold\" aria-pressed=\"true\"><b>B</b></button>\n              <button class=\"tb\" type=\"button\" aria-label=\"Italic\"><i style=\"font-family:Georgia,serif\">I</i></button>\n              <span class=\"tsep\"></span>\n              <button class=\"tb\" type=\"button\" aria-label=\"Highlight\"><mark class=\"rt-hl\" style=\"font-weight:600\">H</mark></button>\n              <button class=\"tb\" type=\"button\" aria-label=\"Key term\"><span class=\"rt-term\">Term</span></button>\n              <button class=\"tb\" type=\"button\" aria-label=\"Code\"><code style=\"font:600 12px var(--sp-mono)\">{ }</code></button>\n              <button class=\"tb\" type=\"button\" aria-label=\"Link\"><svg width=\"16\" height=\"16\"><use href=\"#i-link\"/></svg></button>\n            </div>\n<div class=\"barea\">Your operator runs that week’s skill before the live build, **by Tuesday night**, and the owner reads what it finds. _You don’t need to understand every line yet._ The goal is that ==both of you show up Wednesday with the findings open==. Week 1’s skill is `Map Your Spend`.</div>\n          </div>\n          <div class=\"bfield\">\n            <div class=\"btool\"><span class=\"label\" style=\"padding:0 6px\">Live preview</span></div>\n            <div class=\"bprev\">Your <span class=\"rt-term\">operator</span> runs that week’s skill before the live build, <b>by Tuesday night</b>, and the owner reads what it finds. <i>You don’t need to understand every line yet.</i> The goal is that <mark class=\"rt-hl\">both of you show up Wednesday with the findings open</mark>. Week 1’s skill is <code class=\"rt-code\">Map Your Spend</code>.</div>\n          </div>\n        </div>\n\n        <h3 class=\"sec-h\" style=\"margin-top:var(--sp-s5);font-size:20px\">Buttons: hover, press and focus</h3>\n        <div class=\"gallery\" id=\"gallery\">\n          <button class=\"btn btn-primary\" type=\"button\"><span class=\"aim-roll\"><span>Primary</span><span aria-hidden=\"true\">Primary</span></span></button>\n          <a class=\"btn btn-accent btn-arrow\" href=\"#\" onclick=\"return false\" id=\"continue\"><span class=\"aim-roll\"><span>Continue step 3</span><span aria-hidden=\"true\">Continue step 3</span></span><svg class=\"arrow\" width=\"16\" height=\"16\"><use href=\"#i-arrow\"/></svg></a>\n          <button class=\"btn btn-secondary\" type=\"button\"><svg width=\"14\" height=\"14\"><use href=\"#i-eye\"/></svg><span class=\"aim-roll\"><span>Secondary</span><span aria-hidden=\"true\">Secondary</span></span></button>\n          <button class=\"btn btn-ghost\" type=\"button\">Ghost</button>\n          <a class=\"inline\" href=\"#\" onclick=\"return false\">Inline link</a>\n        </div>\n      </section>";
const FLAG = "<div class=\"mock-flag\"><span><b>MOCKUP</b> · learn.amplifiedimpact.io · Week 0 · Step 2 · v3 polish pass · not live</span><span>Geist · forest · energy · energy-bright · bone · black</span></div>";

export function MockFlag() {
  return <div style={{ display: 'contents' }} dangerouslySetInnerHTML={{ __html: FLAG }} />;
}

export function ReviewSection() {
  const onClick = (e) => {
    const b = e.target.closest('[data-copy]'); if (!b) return;
    const text = b.closest('.copyblock')?.querySelector('pre')?.textContent || '';
    navigator.clipboard?.writeText(text).catch(() => {});
    const spans = [...b.querySelectorAll('.aim-roll > span')];
    const old = spans[0].textContent; spans.forEach((s) => { s.textContent = 'Copied'; });
    setTimeout(() => spans.forEach((s) => { s.textContent = old; }), 1400);
  };
  // display:contents keeps the wrapper out of layout, so .main's flex gap sees the <section> itself.
  return <div style={{ display: 'contents' }} onClick={onClick} dangerouslySetInnerHTML={{ __html: HTML }} />;
}
